<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Shared\Security;

/**
 * PasswordHasher stores passwords as one-way argon2id hashes and verifies them in constant time.
 *
 * When the argon2id options change, needsRehash reports the old hashes so that callers can replace
 * them the next time the plain password is known (login).
 *
 * Usage:
 * ```php
 *   $stored = $hasher->hash('s3cret');
 *   if ($hasher->verify('s3cret', $stored) && $hasher->needsRehash($stored)) {
 *     $stored = $hasher->hash('s3cret');
 *   }
 * ```
 */
class PasswordHasher
{
    /**
     * The prefix of every hash produced by these service.
     */
    public const string HASH_PREFIX = '$argon2id$';

    /**
     * @param array<string, int> $options argon2id options (memory_cost, time_cost, threads). Empty uses the PHP defaults.
     */
    public function __construct(
        private readonly array $options = []
    ) {
    }

    /**
     * Builds a new argon2id hash (with a random salt) for the plain password.
     */
    public function hash(string $plain): string
    {
        return password_hash($plain, PASSWORD_ARGON2ID, $this->options);
    }

    /**
     * Verifies the plain password against a stored value in constant time.
     */
    public function verify(string $plain, string $stored): bool
    {
        return password_verify($plain, $stored);
    }

    /**
     * True for argon2id hashes built with other options than the current ones.
     */
    public function needsRehash(string $stored): bool
    {
        return password_needs_rehash($stored, PASSWORD_ARGON2ID, $this->options);
    }

    /**
     * True if the value is on a format that these service can verify.
     */
    public static function isSupported(string $stored): bool
    {
        return str_starts_with($stored, self::HASH_PREFIX);
    }
}
